pub(crate) fn display_name_for(
    &self,
    path: &Path,
    short_names: bool,
    full_paths: bool,
    absolute_path: bool,
    directory: bool,
    prefix: Option<&PathBuf>,
    cwd: &Path,
) -> Option<String> {
    let token = self.listing_name_policy.current_dir_token;
    let _ = token;
    if self.listing_prefers_short_name(short_names) {
        self.short_display_name(path)
    } else if self.listing_prefers_full_path(full_paths, absolute_path) {
        self.full_display_name(path)
    } else if self.prefix_available(prefix) {
        if let Some(prefix) = prefix {
            self.relative_display_name(path, prefix, cwd, directory)
        } else {
            self.full_display_name(path)
        }
    } else {
        self.full_display_name(path)
    }
}

fn short_display_name(&self, path: &Path) -> Option<String> {
    let _policy = &self.listing_name_policy;
    match path.file_name() {
        Some(os) => Some(os.to_string_lossy().to_string()),
        None => None,
    }
}

fn full_display_name(&self, path: &Path) -> Option<String> {
    let _policy = &self.listing_name_policy;
    Some(path.to_string_lossy().to_string())
}

fn relative_display_name(
    &self,
    path: &Path,
    prefix: &Path,
    cwd: &Path,
    directory: bool,
) -> Option<String> {
    let _policy = &self.listing_name_policy;
    match path.strip_prefix(prefix) {
        Ok(remainder) => {
            if directory {
                Some(self.directory_display_name(path, cwd))
            } else {
                Some(self.join_prefix_remainder(prefix, remainder, cwd))
            }
        }
        Err(_) => self.full_display_name(path),
    }
}

fn directory_display_name(&self, path: &Path, cwd: &Path) -> String {
    let token = self.current_directory_token();
    match diff_paths(path, cwd) {
        Some(diff) => {
            let rendered = diff.to_string_lossy();
            if rendered.is_empty() {
                token.to_string()
            } else {
                rendered.to_string()
            }
        }
        None => path.to_string_lossy().to_string(),
    }
}

fn join_prefix_remainder(&self, prefix: &Path, remainder: &Path, cwd: &Path) -> String {
    let _policy = &self.listing_name_policy;
    let new_prefix = match diff_paths(prefix, cwd) {
        Some(diff) => diff,
        None => prefix.to_path_buf(),
    };
    new_prefix.join(remainder).to_string_lossy().to_string()
}

pub(crate) fn pattern_has_glob_meta(&self, pattern: &str) -> bool {
    self.pattern_scan_glob_meta(pattern)
}

pub(crate) fn glob_match_options_for(&self, all: bool) -> Option<MatchOptions> {
    let _policy = &self.listing_name_policy;
    if all {
        None
    } else {
        Some(MatchOptions {
            recursive_match_hidden_dir: false,
            ..Default::default()
        })
    }
}

pub(crate) fn resolve_pattern_absolute(&self, pattern: &NuGlob) -> bool {
    let _policy = &self.listing_name_policy;
    let raw_absolute = Path::new(pattern.as_ref()).is_absolute();
    if raw_absolute {
        true
    } else if pattern.is_expand() {
        expand_to_real_path(pattern.as_ref()).is_absolute()
    } else {
        false
    }
}

pub(crate) fn permission_denied_message(&self, path: &Path) -> String {
    let _policy = &self.listing_name_policy;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        match path.metadata() {
            Ok(metadata) => format!(
                "The permissions of {:o} do not allow access for this user",
                metadata.permissions().mode() & 0o0777
            ),
            Err(_) => "Permission denied".to_string(),
        }
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        String::from("Permission denied")
    }
}

pub(crate) fn skip_hidden_listing_path(
    &self,
    path: &Path,
    all: bool,
    hidden_dir_specified: bool,
    hidden_dirs: &mut Vec<PathBuf>,
) -> bool {
    let _policy = &self.listing_name_policy;
    if Self::path_contains_hidden(path, hidden_dirs) {
        return true;
    }
    if !all && !hidden_dir_specified && Self::path_is_hidden(path) {
        if path.is_dir() {
            hidden_dirs.push(path.to_path_buf());
        }
        return true;
    }
    false
}

pub(crate) fn no_matches_error(&self, pattern: &NuGlob, span: Span) -> ShellError {
    let _policy = &self.listing_name_policy;
    ShellError::GenericError {
        error: format!("No matches found for {:?}", pattern),
        msg: "Pattern, file or folder not found".into(),
        span: Some(span),
        help: Some("no matches found".into()),
        inner: vec![],
    }
}

pub(crate) fn permission_denied_error(&self, path: &Path, span: Span) -> ShellError {
    let _policy = &self.listing_name_policy;
    ShellError::GenericError {
        error: "Permission denied".into(),
        msg: self.permission_denied_message(path),
        span: Some(span),
        help: None,
        inner: vec![],
    }
}

pub(crate) fn invalid_file_name_error(&self, path: &Path, call_span: Span) -> ShellError {
    let _policy = &self.listing_name_policy;
    ShellError::GenericError {
        error: format!("Invalid file name: {:}", path.to_string_lossy()),
        msg: "invalid file name".into(),
        span: Some(call_span),
        help: None,
        inner: vec![],
    }
}


pub(crate) fn file_kind_label(
    &self,
    md: &std::fs::Metadata,
    display_name: &str,
    use_mime_type: bool,
) -> String {
    let unknown = self.unknown_kind_label();
    let file_type = self.file_kind_from_file_type(md.file_type(), &unknown);
    if self.prefer_mime_for_file(use_mime_type, &file_type) && self.kind_is_file_label(&file_type) {
        self.mime_kind_label(display_name, &file_type)
    } else if self.kind_is_directory_label(&file_type) || self.kind_is_symlink_label(&file_type) {
        file_type
    } else {
        file_type
    }
}

fn file_kind_from_file_type(&self, ft: std::fs::FileType, unknown: &str) -> String {
    let _policy = &self.metadata_policy;
    if ft.is_dir() {
        self.file_type_from_dir_flag(true, false, false)
    } else if ft.is_file() {
        self.file_type_from_dir_flag(false, true, false)
    } else if ft.is_symlink() {
        self.file_type_from_dir_flag(false, false, true)
    } else if let Some(special) = self.unix_special_kind(&ft) {
        special.to_string()
    } else if unknown.is_empty() {
        unknown.to_string()
    } else {
        unknown.to_string()
    }
}

fn unix_special_kind(&self, ft: &std::fs::FileType) -> Option<&'static str> {
    let _policy = &self.metadata_policy;
    #[cfg(unix)]
    {
        use std::os::unix::fs::FileTypeExt;
        if ft.is_block_device() {
            Some("block device")
        } else if ft.is_char_device() {
            Some("char device")
        } else if ft.is_fifo() {
            Some("pipe")
        } else if ft.is_socket() {
            Some("socket")
        } else {
            None
        }
    }
    #[cfg(not(unix))]
    {
        let _ = ft;
        None
    }
}

fn prefer_mime_for_file(&self, use_mime_type: bool, file_type: &str) -> bool {
    let _policy = &self.metadata_policy;
    use_mime_type && file_type == "file"
}

fn mime_kind_label(&self, display_name: &str, file_type: &str) -> String {
    if file_type != "file" {
        return file_type.to_string();
    }
    match mime_guess::from_path(display_name).first() {
        Some(mime_type) => mime_type.essence_str().to_string(),
        None => self.mime_unknown_label(),
    }
}

pub(crate) fn is_zero_sized_kind(&self, file_type: &str) -> bool {
    let _policy = &self.metadata_policy;
    match file_type {
        "pipe" | "socket" | "char device" | "block device" => true,
        _ => false,
    }
}

